import type { FastifyReply,FastifyRequest } from 'fastify';import { BlacklistVendorSchema,CreateVendorSchema,UpdateVendorSchema,VendorListQuerySchema,VendorPurchaseOrdersQuerySchema } from '@nexora/shared';import { dataEnvelope,listEnvelope } from '../../core/http/envelope.js';import { AppError } from '../../core/http/errors.js';import type { VendorService } from './vendor.service.js';
function c(r:FastifyRequest){if(!r.auth||!r.tenant)throw new AppError(500,'AUTH_PIPELINE_INVALID','Tenant authorization pipeline was not initialized.');return{auth:r.auth,tenant:r.tenant};}
export class VendorController{constructor(private readonly s:VendorService){}list=async(r:FastifyRequest,p:FastifyReply)=>{const{tenant}=c(r),x=await this.s.list(tenant,VendorListQuerySchema.parse(r.query));return p.code(200).send(listEnvelope(x.rows,{page:x.page,pageSize:x.pageSize,total:x.total,requestId:r.id}));};get=async(r:FastifyRequest<{Params:{id:string}}>,p:FastifyReply)=>{const{tenant}=c(r);return p.code(200).send(dataEnvelope(await this.s.get(tenant,r.params.id),r.id));};create=async(r:FastifyRequest,p:FastifyReply)=>{const{auth,tenant}=c(r);return p.code(201).send(dataEnvelope(await this.s.create(tenant,{userId:auth.userId,ip:r.ip},CreateVendorSchema.parse(r.body)),r.id));};update=async(r:FastifyRequest<{Params:{id:string}}>,p:FastifyReply)=>{const{auth,tenant}=c(r);return p.code(200).send(dataEnvelope(await this.s.update(tenant,{userId:auth.userId,ip:r.ip},r.params.id,UpdateVendorSchema.parse(r.body)),r.id));};performance=async(r:FastifyRequest<{Params:{id:string}}>,p:FastifyReply)=>{const{tenant}=c(r);return p.code(200).send(dataEnvelope(await this.s.performance(tenant,r.params.id),r.id));};purchaseOrders=async(r:FastifyRequest<{Params:{id:string}}>,p:FastifyReply)=>{const{tenant}=c(r);const q=VendorPurchaseOrdersQuerySchema.parse(r.query);const x=await this.s.purchaseOrders(tenant,r.params.id,q);return p.code(200).send(listEnvelope(x.rows,{page:x.page,pageSize:x.pageSize,total:x.total,requestId:r.id}));};blacklist=async(r:FastifyRequest<{Params:{id:string}}>,p:FastifyReply)=>{const{auth,tenant}=c(r);const input=BlacklistVendorSchema.parse(r.body);return p.code(200).send(dataEnvelope(await this.s.blacklist(tenant,{userId:auth.userId,ip:r.ip},r.params.id,input),r.id));};}